import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, TextField, InputAdornment, Button, CircularProgress,
  Grid, Card, CardContent, CardActions, Avatar, Chip, IconButton, Tooltip,
  FormControl, InputLabel, Select, MenuItem, TablePagination, Collapse,
  Badge,
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import PhoneIcon from '@mui/icons-material/Phone';
import SmartphoneIcon from '@mui/icons-material/Smartphone';
import EmailIcon from '@mui/icons-material/Email';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import BadgeIcon from '@mui/icons-material/Badge';
import DownloadIcon from '@mui/icons-material/Download';
import FilterListIcon from '@mui/icons-material/FilterList';
import ViewModuleIcon from '@mui/icons-material/ViewModule';
import ViewListIcon from '@mui/icons-material/ViewList';
import EmergencyIcon from '@mui/icons-material/ContactEmergency';
import { useDepartments } from '../core/hooks/useEmployees';

const PhonebookPage = () => {
  const { t } = useTranslation();
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(24);
  const [search, setSearch] = useState('');
  const [department, setDepartment] = useState('');
  const [viewMode, setViewMode] = useState('grid');
  const [showFilters, setShowFilters] = useState(false);

  const [debouncedSearch, setDebouncedSearch] = useState('');
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 400);
    return () => clearTimeout(timer);
  }, [search]);

  const { data: departments } = useDepartments();

  const { data, isLoading } = useQuery({
    queryKey: ['phonebook', page, rowsPerPage, debouncedSearch, department],
    queryFn: () => axiosInstance.get('/phonebook/', {
      params: {
        page: page + 1, page_size: rowsPerPage,
        search: debouncedSearch || undefined,
        department: department || undefined,
      }
    }).then(r => r.data),
  });

  const employees = data?.results || [];
  const totalCount = data?.count || 0;

  const exportUrl = `${axiosInstance.defaults.baseURL}/phonebook/export/?search=${debouncedSearch}&department=${department}`;

  // Generate consistent avatar colors based on name
  const avatarColors = [
    'linear-gradient(135deg, #6366f1, #8b5cf6)',
    'linear-gradient(135deg, #ec4899, #f472b6)',
    'linear-gradient(135deg, #10b981, #34d399)',
    'linear-gradient(135deg, #f59e0b, #fbbf24)',
    'linear-gradient(135deg, #3b82f6, #60a5fa)',
    'linear-gradient(135deg, #8b5cf6, #a78bfa)',
  ];

  const getAvatarColor = (name) => {
    let hash = 0;
    for (let i = 0; i < (name || '').length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
    return avatarColors[Math.abs(hash) % avatarColors.length];
  };

  const CardView = () => (
    <Grid container spacing={2}>
      {employees.length === 0 ? (
        <Grid item xs={12}><Typography textAlign="center" color="textSecondary" sx={{ p: 6 }}>{t('table.no_results')}</Typography></Grid>
      ) : (
        employees.map(emp => (
          <Grid item xs={12} sm={6} md={4} lg={3} key={emp.id}>
            <Card sx={{
              height: '100%', display: 'flex', flexDirection: 'column',
              '&:hover .avatar-ring': { transform: 'scale(1.05)' }
            }}>
              <CardContent sx={{ textAlign: 'center', pt: 3 }}>
                <Avatar className="avatar-ring" sx={{
                  width: 64, height: 64, mx: 'auto', mb: 1.5, fontSize: 24, fontWeight: 700,
                  background: getAvatarColor(emp.full_name),
                  boxShadow: '0 4px 16px rgba(99,102,241,0.25)',
                  transition: 'transform 0.3s ease',
                }}>
                  {emp.first_name?.charAt(0)}{emp.last_name?.charAt(0)}
                </Avatar>
                <Typography variant="subtitle1" fontWeight={700} noWrap>{emp.full_name}</Typography>
                <Chip icon={<BadgeIcon sx={{ fontSize: 14 }} />} label={emp.employee_id} size="small" variant="outlined" sx={{ mt: 0.5 }} />
                <Typography variant="caption" color="textSecondary" display="block" sx={{ mt: 0.5 }}>
                  {emp.department} — {emp.job_title}
                </Typography>
              </CardContent>
              <CardActions sx={{ justifyContent: 'center', gap: 1, pb: 2 }}>
                <Tooltip title={emp.mobile || ''}>
                  <IconButton size="small" color="primary" component="a" href={`tel:${emp.mobile}`}
                    sx={{ bgcolor: 'rgba(99,102,241,0.1)', '&:hover': { bgcolor: 'rgba(99,102,241,0.2)' } }}>
                    <SmartphoneIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
                {emp.phone && (
                  <Tooltip title={emp.phone}>
                    <IconButton size="small" color="secondary" component="a" href={`tel:${emp.phone}`}
                      sx={{ bgcolor: 'rgba(236,72,153,0.1)', '&:hover': { bgcolor: 'rgba(236,72,153,0.2)' } }}>
                      <PhoneIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                )}
                {emp.email && (
                  <Tooltip title={emp.email}>
                    <IconButton size="small" color="success" component="a" href={`mailto:${emp.email}`}
                      sx={{ bgcolor: 'rgba(16,185,129,0.1)', '&:hover': { bgcolor: 'rgba(16,185,129,0.2)' } }}>
                      <EmailIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                )}
                {emp.emergency_contact_phone && (
                  <Tooltip title={`${t('employees.emergency_contact')}: ${emp.emergency_contact_name || ''} - ${emp.emergency_contact_phone}`}>
                    <IconButton size="small" color="warning" component="a" href={`tel:${emp.emergency_contact_phone}`}
                      sx={{ bgcolor: 'rgba(245,158,11,0.1)', '&:hover': { bgcolor: 'rgba(245,158,11,0.2)' } }}>
                      <EmergencyIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                )}
              </CardActions>
            </Card>
          </Grid>
        ))
      )}
    </Grid>
  );

  const ListView = () => (
    <Grid container spacing={1}>
      {employees.length === 0 ? (
        <Grid item xs={12}><Typography textAlign="center" color="textSecondary" sx={{ p: 6 }}>{t('table.no_results')}</Typography></Grid>
      ) : (
        employees.map(emp => (
          <Grid item xs={12} key={emp.id}>
            <Card variant="outlined">
              <CardContent sx={{ py: 1.5, display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
                <Avatar sx={{
                  width: 40, height: 40, fontSize: 16, fontWeight: 700,
                  background: getAvatarColor(emp.full_name),
                }}>
                  {emp.first_name?.charAt(0)}{emp.last_name?.charAt(0)}
                </Avatar>
                <Box sx={{ flex: 1, minWidth: 120 }}>
                  <Typography variant="body2" fontWeight={600}>{emp.full_name}</Typography>
                  <Typography variant="caption" color="textSecondary">{emp.department}</Typography>
                </Box>
                <Chip icon={<SmartphoneIcon sx={{ fontSize: 14 }} />} label={emp.mobile} size="small" variant="outlined"
                  component="a" href={`tel:${emp.mobile}`} clickable />
                {emp.phone && <Chip icon={<PhoneIcon sx={{ fontSize: 14 }} />} label={emp.phone} size="small" variant="outlined"
                  component="a" href={`tel:${emp.phone}`} clickable />}
                {emp.email && <Chip icon={<EmailIcon sx={{ fontSize: 14 }} />} label={emp.email} size="small" variant="outlined"
                  component="a" href={`mailto:${emp.email}`} clickable />}
                <Chip icon={<BadgeIcon sx={{ fontSize: 14 }} />} label={emp.employee_id} size="small" />
              </CardContent>
            </Card>
          </Grid>
        ))
      )}
    </Grid>
  );

  return (
    <Box>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3, flexWrap: 'wrap', gap: 1 }}>
        <Typography variant="h4" fontWeight={800}>{t('phonebook.title')}</Typography>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Tooltip title={viewMode === 'grid' ? t('documents.list_view') : t('documents.grid_view')}>
            <IconButton onClick={() => setViewMode(v => v === 'grid' ? 'list' : 'grid')}>
              {viewMode === 'grid' ? <ViewListIcon /> : <ViewModuleIcon />}
            </IconButton>
          </Tooltip>
          <Button variant="contained" startIcon={<DownloadIcon />} component="a" href={exportUrl} target="_blank">
            {t('phonebook.export_excel')}
          </Button>
        </Box>
      </Box>

      {/* Search & Filter Bar */}
      <Paper sx={{ p: 2, mb: 3 }}>
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap' }}>
          <TextField
            size="small"
            placeholder="جستجو در دفترچه تلفن..."
            value={search}
            onChange={e => { setSearch(e.target.value); setPage(0); }}
            InputProps={{
              startAdornment: <InputAdornment position="start"><SearchIcon color="action" /></InputAdornment>,
            }}
            sx={{ flex: 1, minWidth: 250 }}
          />
          <Button
            startIcon={<FilterListIcon />}
            onClick={() => setShowFilters(!showFilters)}
            color={showFilters ? 'primary' : 'inherit'}
            variant={showFilters ? 'contained' : 'outlined'}
            size="small"
          >
            {t('common.filter')} {showFilters ? '' : ''}
          </Button>
        </Box>
        <Collapse in={showFilters}>
          <Box sx={{ mt: 1.5, display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap' }}>
            <FormControl size="small" sx={{ minWidth: 200 }}>
              <InputLabel>{t('employees.department')}</InputLabel>
              <Select value={department} label={t('employees.department')}
                onChange={e => { setDepartment(e.target.value); setPage(0); }}>
                <MenuItem value="">{t('common.all')}</MenuItem>
                {Array.isArray(departments) && departments.map(d => (
                  <MenuItem key={d.id} value={d.id}>{d.name}</MenuItem>
                ))}
              </Select>
            </FormControl>
            <Button size="small" onClick={() => { setDepartment(''); setSearch(''); setPage(0); }}>
              پاک‌سازی فیلترها
            </Button>
          </Box>
        </Collapse>
      </Paper>

      {/* Results Count */}
      <Typography variant="body2" color="textSecondary" sx={{ mb: 2 }}>
        {t('table.total', { count: totalCount })}
      </Typography>

      {/* Content */}
      {isLoading ? (
        <Box sx={{ textAlign: 'center', p: 6 }}><CircularProgress /></Box>
      ) : (
        viewMode === 'grid' ? <CardView /> : <ListView />
      )}

      {/* Pagination */}
      {totalCount > rowsPerPage && (
        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 3 }}>
          <TablePagination
            component="div"
            count={totalCount}
            page={page}
            onPageChange={(e, p) => setPage(p)}
            rowsPerPage={rowsPerPage}
            onRowsPerPageChange={e => { setRowsPerPage(Number(e.target.value)); setPage(0); }}
            rowsPerPageOptions={[12, 24, 48, 72]}
            labelRowsPerPage="تعداد در صفحه:"
          />
        </Box>
      )}
    </Box>
  );
};

export default PhonebookPage;
